/**
 * Brisca practice: endgame problems proved by the exact solver (generated by
 * scripts/generate-brisca-endgames.ts), and five generated drills on the lesson runner: win the
 * trick, the points in your hand, count a pile, count the trumps still out, and the señas
 * flash cards (read your partner's sign, or make the sign for a card you hold).
 */
import type { Lesson } from '../../../teach/lesson';
import type { Problem } from '../../../teach/problem';
import type { DrillDef, PracticePack } from '../../practice';
import { briscaLessonGame } from '../learn/game';
import type { Card, Sign, Suit } from '../rules';
import { DECK, position, PUERTO_RICO, signCard, SIGNS, SUITS, suitOf, trickWinner } from '../rules';
import { cardName } from '../ui/names';

interface EndgameFile {
  readonly problems: readonly { id: string; position: string; setup: string | null; line: string[]; rating: number; themes: string[] }[];
}

function draw(random: () => number, n: number, from: readonly Card[] = DECK): Card[] {
  const pool = [...from];
  const out: Card[] = [];
  while (out.length < n && pool.length > 0) out.push(pool.splice(Math.floor(random() * pool.length), 1)[0] as Card);
  return out;
}

const pickSuit = (random: () => number): Suit => SUITS[Math.floor(random() * SUITS.length)] as Suit;

function lesson(id: string, title: string, start: string, steps: Lesson['steps']): Lesson {
  return { id: `brisca.drill.${id}`, gameId: 'brisca', stage: 'table', title, minutes: 1, start, steps };
}

/** Win the trick: the CPU leads, you pick a card that beats it. */
function trickDrill(random: () => number): Lesson {
  for (let tries = 0; ; tries++) {
    const trump = pickSuit(random);
    const [led, ...rest] = draw(random, 6);
    const me = rest.slice(0, 3);
    const them = rest.slice(3, 5);
    const winners = me.filter((c) => trickWinner([{ seat: 1, card: led as Card }, { seat: 0, card: c }], trump, PUERTO_RICO) === 0);
    if ((winners.length === 0 || winners.length === 3) && tries < 50) continue;
    const start = position({ trump, me, them, trick: [{ seat: 1, card: led as Card }], leader: 1 });
    const wrong: Record<string, string> = {};
    for (const c of me) if (!winners.includes(c)) wrong[c] = suitOf(c) === trump || suitOf(c) === suitOf(led as Card) ? 'That card is not strong enough to beat the card led.' : 'A card of another suit, not trumps, never wins a trick.';
    return lesson('trick', 'Win the trick', start, [
      { kind: 'askMove', text: `The CPU led the ${cardName(led as Card)}. Play a card that wins the trick.`, accept: winners, wrong, claim: 'legal', success: 'Right, that card takes the trick.' },
    ]);
  }
}

/** The points in your hand, to learn the card values. */
function valuesDrill(random: () => number): Lesson {
  const cards = draw(random, 6);
  const start = position({ trump: pickSuit(random), me: cards.slice(0, 3), them: cards.slice(3) });
  return lesson('values', 'Card values', start, [{ kind: 'askNumber', text: 'How many points are in your three cards? As {value:A}, Tres {value:3}, Rey {value:R}, Caballo {value:C}, Sota {value:S}.', answer: 'hand:points', success: 'Yes, {hand:points}.' }]);
}

/** Count a pile of won tricks, face up. */
function pileDrill(random: () => number): Lesson {
  const cards = draw(random, 16);
  const pile = cards.slice(0, 8 + 2 * Math.floor(random() * 3));
  const start = position({ trump: pickSuit(random), me: cards.slice(12, 15), them: cards.slice(15, 16).concat(draw(random, 2, DECK.filter((c) => !cards.includes(c)))), wonMe: pile });
  return lesson('pile', 'Count the pile', start, [{ kind: 'askNumber', text: 'Your tricks are turned face up. How many points are in them?', answer: 'pile:me', success: 'Right: {pile:me}.', openPiles: true }]);
}

/** Count the trumps not yet seen, from the tricks played and your hand. */
function trumpsDrill(random: () => number): Lesson {
  const trump = pickSuit(random);
  const turnedRank = ['4', '5', '6', 'S', 'C', 'R'][Math.floor(random() * 6)] as string;
  const turned = `${turnedRank}${trump}` as Card;
  const rest = DECK.filter((c) => c !== turned);
  const cards = draw(random, 18, rest);
  const start = position({ trump: turned, me: cards.slice(0, 3), them: cards.slice(3, 6), wonMe: cards.slice(6, 12), wonThem: cards.slice(12, 18) });
  return lesson('trumps', 'Count the trumps', start, [{ kind: 'askNumber', text: 'Every trick played so far is face up. Counting your hand and the turned card too, how many trumps have you not seen?', answer: 'trumps:unseen', success: 'Yes, {trumps:unseen} still out.', openPiles: true }]);
}

/** What each sign looks like, and the card it stands for, in words. */
const GESTURE: Readonly<Record<Sign, string>> = {
  A: 'stretches the lips over the teeth',
  second: 'twists the mouth to one side',
  R: 'glances upwards',
  C: 'shows the tip of the tongue',
  S: 'shrugs one shoulder',
};
const CARD: Readonly<Record<Sign, string>> = { A: 'the As', second: 'the Tres', R: 'the Rey', C: 'the Caballo', S: 'the Sota' };
const PLAIN: Readonly<Record<Sign, string>> = { A: 'lips stretched over the teeth', second: 'the mouth twisted to one side', R: 'a glance upwards', C: 'the tip of the tongue', S: 'one shoulder shrugged' };

/**
 * Señas flash cards. Half the time your partner makes a sign, drawn by their name without its
 * name, and you say what it means; otherwise you hold two high trumps and make the sign for one.
 */
function senasDrill(random: () => number): Lesson {
  const trump = pickSuit(random);
  const config = { players: 4 as const, signals: 'señas' as const };
  const shuffled = [...SIGNS].sort(() => random() - 0.5);
  const [sign, other, third] = shuffled as [Sign, Sign, Sign];
  const blanks = DECK.filter((c) => suitOf(c) !== trump && !['A', '3'].includes(c[0] as string));
  const pick = draw(random, 9, blanks);
  if (random() < 0.5) {
    // Read the sign: your partner holds the card and has signed it.
    const card = signCard(sign, trump, PUERTO_RICO);
    const start = position({ trump, me: pick.slice(0, 3), them: [], others: [pick.slice(3, 6), [card, ...pick.slice(6, 8)], [pick[8] as Card, ...draw(random, 2, blanks.filter((c) => !pick.includes(c)))]], signals: [{ seat: 2, sign }], config });
    const options = [sign, other, third].sort(() => random() - 0.5).map((s) => (s === sign ? { text: `${CARD[s]} of trumps`, correct: true, why: `Yes: your partner ${GESTURE[s]}, the sign for ${CARD[s]}.` } : { text: `${CARD[s]} of trumps`, why: `For ${CARD[s]} your partner ${GESTURE[s]}. This sign is ${CARD[sign]}.` }));
    return { ...lesson('senas', 'Señas', start, [{ kind: 'askChoice', marks: ['hide-sign-names'], text: 'Your partner makes the sign drawn by their name. Which card of trumps do they hold?', options }]) };
  }
  // Make the sign: you hold two high trumps; sign the one asked for.
  const mine = [signCard(sign, trump, PUERTO_RICO), signCard(other, trump, PUERTO_RICO), pick[0] as Card];
  const start = position({ trump, me: mine, them: [], others: [pick.slice(1, 4), pick.slice(4, 7), [pick[7] as Card, pick[8] as Card, ...draw(random, 1, blanks.filter((c) => !pick.includes(c)))]], config });
  return lesson('senas', 'Señas', start, [
    { kind: 'askMove', marks: ['hide-sign-names'], text: `Tell your partner you hold ${CARD[sign]} of trumps: open Señas and make its sign.`, accept: [`sign:${sign}`], wrong: { [`sign:${other}`]: `That is the sign for ${CARD[other]}. The sign for ${CARD[sign]} is ${PLAIN[sign]}.` }, claim: 'legal', success: `Right: ${CARD[sign]}.` },
  ]);
}

export async function loadBriscaPractice(): Promise<PracticePack> {
  const file = (await import('./endgames.json')).default as unknown as EndgameFile;
  const problems: Problem[] = file.problems.map((p) => ({ id: p.id, position: p.position, setup: p.setup, line: p.line, rating: p.rating, themes: p.themes, openHand: true }));
  const drills: DrillDef[] = [
    { id: 'drill-trick', make: trickDrill },
    { id: 'drill-values', make: valuesDrill },
    { id: 'drill-pile', make: pileDrill },
    { id: 'drill-trumps', make: trumpsDrill },
    { id: 'drill-senas', make: senasDrill },
  ];
  return { problems, sets: [{ id: 'endgames', themes: ['endgame'], chips: ['lead', 'follow'] }], drills, attribution: null, game: briscaLessonGame, themeOrder: ['lead', 'follow', 'endgame'] };
}
